import std.io

pub type AppError = Failed(String)

interface Describe {
    fn describe(self) -> String
}

record Point { x: Int64, y: Int64 }
newtype Celsius(Int64)
newtype Tag(String)

impl Describe for Point {
    fn describe(self) -> String { "point" }
}
impl Describe for Celsius {
    fn describe(self) -> String { "c" }
}
impl Describe for Tag {
    fn describe(self) -> String { "t" }
}

fn makePoint(seed: Int64) -> Dyn<Describe> {
    return Dyn<Describe>(Point { x: seed, y: seed + 1 })
}

fn makeCelsius(n: Int64) -> Dyn<Describe> {
    return Dyn<Describe>(Celsius(n))
}

fn makeTag(s: String) -> Dyn<Describe> {
    return Dyn<Describe>(Tag(s))
}

fn pick(a: Dyn<Describe>, b: Dyn<Describe>, first: Bool) -> Dyn<Describe> {
    if first {
        return a
    }
    return b
}

fn width(d: Dyn<Describe>) -> Int64 {
    return 1
}

pub fn main() effect io -> Result<(), AppError> {
    let p = makePoint(3)
    let c = makeCelsius(7)
    let t = makeTag("hello")
    let one = pick(p, c, true)
    let two = pick(c, t, false)
    let n = width(one) + width(two) + width(p) + width(t) + width(c)
    io.println("${n}")
    return Ok(())
}
